import React from 'react';
import { Grid, Typography, Divider, Box } from '@mui/material';
import { useTranslation } from 'react-i18next';
import StatusBadge from '../ui/StatusBadge';
import { toJalali } from '../../utils/dateUtils';

const DATE_FIELDS = [
  'hire_date', 'probation_end_date', 'official_date',
  'contract_start_date', 'contract_end_date', 'status_change_date'
];

const InfoRow = ({ label, value, fieldName }) => {
  const displayValue = fieldName && DATE_FIELDS.includes(fieldName) ? toJalali(value) : (value || '—');
  return (
    <Grid item xs={12} sm={6} md={4}>
      <Box sx={{ mb: 1.5 }}>
        <Typography variant="caption" color="textSecondary">{label}</Typography>
        <Typography variant="body2" fontWeight={500}>{displayValue}</Typography>
      </Box>
    </Grid>
  );
};

const EmploymentTab = ({ employee }) => {
  const { t } = useTranslation();
  const e = employee || {};

  return (
    <Box>
      <Typography variant="h6" gutterBottom>{t('employees.employment_details')}</Typography>
      <Divider sx={{ mb: 2 }} />
      <Grid container spacing={1}>
        <InfoRow label={t('employees.employee_id')} value={e.employee_id} />
        <InfoRow label={t('employees.hire_date')} value={e.hire_date} fieldName="hire_date" />
        <InfoRow label={t('employees.probation_end_date')} value={e.probation_end_date} fieldName="probation_end_date" />
        <InfoRow label={t('employees.official_date')} value={e.official_date} fieldName="official_date" />
      </Grid>

      <Typography variant="h6" gutterBottom sx={{ mt: 3 }}>{t('employees.position_info')}</Typography>
      <Divider sx={{ mb: 2 }} />
      <Grid container spacing={1}>
        <InfoRow label={t('employees.department')} value={e.department_detail?.name} />
        <InfoRow label={t('employees.job_title')} value={e.job_title_detail?.name} />
        <InfoRow label={t('employees.work_location')} value={e.work_location_detail?.name} />
        <InfoRow label={t('employees.insurance_list')} value={e.insurance_list_detail?.name} />
      </Grid>

      <Typography variant="h6" gutterBottom sx={{ mt: 3 }}>{t('employees.contract_info')}</Typography>
      <Divider sx={{ mb: 2 }} />
      <Grid container spacing={1}>
        <InfoRow label={t('employees.contract_type')} value={e.contract_type_display} />
        <InfoRow label={t('employees.contract_start_date')} value={e.contract_start_date} fieldName="contract_start_date" />
        <InfoRow label={t('employees.contract_end_date')} value={e.contract_end_date} fieldName="contract_end_date" />
      </Grid>

      <Typography variant="h6" gutterBottom sx={{ mt: 3 }}>{t('employees.current_status')}</Typography>
      <Divider sx={{ mb: 2 }} />
      <Grid container spacing={1}>
        <Grid item xs={12} sm={6} md={4}>
          <Box sx={{ mb: 1.5 }}>
            <Typography variant="caption" color="textSecondary">{t('employees.status')}</Typography>
            <Box sx={{ mt: 0.5 }}><StatusBadge status={e.status} /></Box>
          </Box>
        </Grid>
        <InfoRow label={t('employees.status_change_date')} value={e.status_change_date} fieldName="status_change_date" />
        <InfoRow label={t('employees.work_shift')} value={e.work_shift_display} />
      </Grid>

      {e.description && (
        <>
          <Typography variant="h6" gutterBottom sx={{ mt: 3 }}>{t('employees.description')}</Typography>
          <Divider sx={{ mb: 2 }} />
          <Typography variant="body2">{e.description}</Typography>
        </>
      )}
    </Box>
  );
};

export default EmploymentTab;
